import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        t = int(next(iterator))
    except StopIteration:
        return

    results = []

    for _ in range(t):
        try:
            a = next(iterator)
            b = next(iterator)
        except StopIteration:
            break

        n = len(a)
        m = len(b)
        i = 0
        j = 0
        res = []

        while i < n and j < m:
            if a[i:] < b[j:]:
                res.append(a[i])
                i += 1
            else:
                res.append(b[j])
                j += 1

        if i < n:
            res.append(a[i:])
        if j < m:
            res.append(b[j:])

        results.append("".join(res))

    for r in results:
        print(r)

if __name__ == '__main__':
    solve()
